#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_padded_message_is_whole_blocks() {
        for n in 0..200usize {
            let padded = pad(&vec![0x61u8; n]);
            assert_eq!(padded.len() % 64, 0);
            assert!(padded.len() > n);
            assert_eq!(padded[n], 0x80);
        }
    }

    #[test]
    fn the_length_is_sixty_four_bits_of_big_endian_bit_count() {
        let padded = pad(b"abc");
        assert_eq!(padded.len(), 64);
        assert_eq!(&padded[56..], &[0, 0, 0, 0, 0, 0, 0, 24]);
        assert_eq!(&padded[..4], &[0x61, 0x62, 0x63, 0x80]);
        assert!(padded[4..56].iter().all(|&b| b == 0));
    }

    #[test]
    fn fifty_six_bytes_needs_a_second_block() {
        assert_eq!(run(), vec![64, 64, 64, 128]);
        assert_eq!(pad(&vec![0u8; 55]).len(), 64);
        assert_eq!(pad(&vec![0u8; 56]).len(), 128);
        assert_eq!(pad(&vec![0u8; 64]).len(), 128);
    }
}

